create function cp7_credit.part_lines(p_part uuid) returns jsonb
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare q cp7_credit.component_parts;c cp7_credit.recognition_components;h cp7_credit.cohorts;ar uuid;
begin
 select *into strict q from cp7_credit.component_parts where id=p_part;
 select *into strict c from cp7_credit.recognition_components where id=q.component_id;
 select h0.*into strict h from cp7_credit.cohorts h0 join cp7_credit.recognition_plans p on p.cohort_id=h0.id where p.id=c.plan_id;
 -- Actual AR account of this return journal, under mapping/account locks.
 -- The source collector must reject unexplained account changes, not invent a
-- reclassification from some unrelated account or choose a new default.
 select distinct jl.account_id into strict ar from erp.journal_lines jl
  where jl.journal_entry_id=h.source_return_journal_id
   and jl.account_id=h.ar_account_id and jl.customer_id=h.customer_id and jl.credit>0;
 if ar=h.credit_account_id then raise exception 'CP7_CREDIT_ACCOUNT_COLLISION';end if;
 return cp7_credit.native_cent_lines(jsonb_build_array(
  jsonb_build_object('account_id',ar,'customer_id',h.customer_id,
   'description','OW04 source-bound recognition',
   'debit',case when q.amount>0 then q.amount else 0 end,
   'credit',case when q.amount<0 then -q.amount else 0 end),
  jsonb_build_object('account_id',h.credit_account_id,'customer_id',h.customer_id,
   'description','OW04 source-bound recognition',
   'debit',case when q.amount<0 then -q.amount else 0 end,
   'credit',case when q.amount>0 then q.amount else 0 end)));
end $$;

create function cp7_credit.assert_bound_post(p_type text,p_source uuid,p_economic date,p_lines jsonb)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare x cp7_credit.posting_scope;c cp7_credit.recognition_components;q cp7_credit.component_parts;h cp7_credit.cohorts;
begin
 select *into strict x from cp7_credit.posting_scope where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid();
 if auth.uid()is null or auth.jwt()->>'role'is distinct from'authenticated'
  or(x.source_type,x.source_id,x.economic_date,x.lines_sha256_pg)is distinct from
   (p_type,p_source,p_economic,cp7_credit.native_lines_sha256(p_lines))then
  raise exception using errcode='42501',message='CP7_CREDIT_PAIRED_POST_SCOPE_REQUIRED';end if;
 if x.post_kind='COMPONENT'then
  perform cp7_credit.validate_component(x.component_id);
  select *into strict c from cp7_credit.recognition_components where id=x.component_id;
  select *into strict q from cp7_credit.component_parts where id=x.part_id and component_id=c.id;
  select h0.*into strict h from cp7_credit.cohorts h0 join cp7_credit.recognition_plans p on p.cohort_id=h0.id where p.id=c.plan_id;
  if p_type<>'CP7_CUSTOMER_CREDIT_RECOGNITION'or p_source<>q.id
   or(x.plan_id,x.source_sale_id,x.source_return_id,x.economic_date,x.transaction_date)is distinct from
    (c.plan_id,h.source_sale_id,h.source_return_id,c.economic_date,c.transaction_date)
   or cp7_credit.native_cent_lines(p_lines)is distinct from cp7_credit.part_lines(q.id)then raise exception 'CP7_CREDIT_COMPONENT_POST_SCOPE_CHANGED';end if;
 else
  perform cp7_credit.assert_return_owner_context(x.source_return_id);
  if p_type<>'SALES_RETURN'or p_source<>x.source_return_id then raise exception 'CP7_CREDIT_RETURN_POST_SCOPE_CHANGED';end if;
 end if;
end $$;

create function cp7_credit.post_component(p_component uuid)returns jsonb
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare c cp7_credit.recognition_components;p cp7_credit.recognition_plans;h cp7_credit.cohorts;
 j uuid;lines jsonb;actual erp.journal_entries;ctx cp7_credit.execution_context;
 q cp7_credit.component_parts;receipt jsonb:='[]';
begin
 select *into strict c from cp7_credit.recognition_components where id=p_component;
 select *into strict p from cp7_credit.recognition_plans where id=c.plan_id;
 select *into strict h from cp7_credit.cohorts where id=p.cohort_id;
 perform cp7_credit.assert_owner_context(p.id);
 -- The owning request envelope returns cached committed receipts before this
-- writer. Never repost a component UUID, even after its journal was reversed.
 if exists(select 1 from cp7_credit.component_journals jj join cp7_credit.component_parts qq on qq.id=jj.part_id where qq.component_id=c.id)then
  raise exception 'CP7_CREDIT_COMPONENT_ALREADY_HAS_HISTORY';end if;
 perform cp7_credit.validate_component(c.id);
 select *into strict ctx from cp7_credit.execution_context where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid()and plan_id=p.id;
 for q in select *from cp7_credit.component_parts where component_id=c.id order by ordinal loop
  lines:=cp7_credit.part_lines(q.id);
  insert into cp7_credit.posting_scope values(pg_backend_pid(),txid_current(),auth.uid(),ctx.request_id,'COMPONENT',
   c.id,q.id,p.id,h.source_sale_id,h.source_return_id,'CP7_CUSTOMER_CREDIT_RECOGNITION',q.id,
   c.economic_date,c.transaction_date,cp7_credit.native_lines_sha256(lines));
  j:=cp7_credit._post_journal_bound('CP7_CUSTOMER_CREDIT_RECOGNITION',q.id,c.economic_date,
   'Kredit retur: pengakuan terikat sumber',lines);
  select *into strict actual from erp.journal_entries where id=j;
  if(actual.source_type,actual.source_id,actual.economic_date,actual.transaction_date,actual.status)is distinct from
   ('CP7_CUSTOMER_CREDIT_RECOGNITION',q.id,c.economic_date,c.transaction_date,'POSTED')then
   raise exception 'CP7_CREDIT_POSTED_PAIR_CHANGED';end if;
  insert into cp7_credit.component_journals values(q.id,j,c.economic_date,c.transaction_date,
   cp7_credit.native_lines_sha256(lines),statement_timestamp());
  if p.plan_kind='ADJUSTMENT'then perform cp7_credit.seal_source_operation_part_v1(q.id);end if;
  receipt:=receipt||jsonb_build_array(jsonb_build_object('part_id',q.id,'journal_id',j));
  delete from cp7_credit.posting_scope where backend_pid=pg_backend_pid()and transaction_id=txid_current();
 end loop;
 perform cp7_credit.assert_owner_context(p.id);
 return jsonb_build_object('component_id',c.id,'parts',receipt);
end $$;

create function cp7_credit.source_inverse_proof_v1(
 p_before jsonb,p_actual jsonb,p_action text,p_source uuid
)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare original jsonb;inverse jsonb;row jsonb;old_row jsonb;expected jsonb;
 old_event jsonb;actual_event jsonb;old_source jsonb;new_source jsonb;
 original_id uuid;inverse_id uuid;original_header erp.journal_entries;inverse_header erp.journal_entries;
 old_payment erp.sales_payments;new_payment erp.sales_payments;fact erp.sales_payment_posting_facts;
 reversal_fact erp.sales_payment_reversal_facts;fact_json jsonb;reversal_json jsonb;
 original_movements jsonb:='[]';new_movements jsonb:='[]';movement jsonb;back jsonb;
 selected_items jsonb;item jsonb;lot jsonb;new_lot jsonb;balance jsonb;new_balance jsonb;
 key text;source_type text;source_key text;n integer;closed date;lawful date;delta numeric;
 sale_id uuid;ar_account uuid;old_facts jsonb;after_facts jsonb;proof jsonb;
begin
 if p_action is null or p_action not in('RETURN_REVERSE','PAYMENT_REVERSE')or p_source is null then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTION_REQUIRED';end if;
 if jsonb_typeof(p_before)is distinct from'object'or jsonb_typeof(p_actual)is distinct from'object'
  or not p_before?&array['sale','items','allocations','payments','payment_posting_facts','payment_reversal_facts',
   'returns','return_items','base_events','journals','advance_links','fg_lots','hpp_versions','stock_movements',
   'inventory_balances','opening_hpp_states','opening_hpp_corrections','po_hpp_states','hpp_accounts',
   'period_snapshot','nonpo_hpp_events','po_hpp_events','hpp_journals']
  or not p_actual?&array['sale','items','allocations','payments','payment_posting_facts','payment_reversal_facts',
   'returns','return_items','base_events','journals','advance_links','fg_lots','hpp_versions','stock_movements',
   'inventory_balances','opening_hpp_states','opening_hpp_corrections','po_hpp_states','hpp_accounts',
   'period_snapshot','nonpo_hpp_events','po_hpp_events','hpp_journals']then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_SNAPSHOT_INCOMPLETE';end if;
 sale_id:=(p_before#>>'{sale,id}')::uuid;
 if sale_id is null or p_actual#>>'{sale,id}'is distinct from sale_id::text
  or p_before->'sale'-array['status','row_version','updated_at']is distinct from
     p_actual->'sale'-array['status','row_version','updated_at']then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_SALE_IDENTITY_CHANGED';end if;
 -- The exact bounded hook is BEFORE Native's only sale-header UPDATE.
 -- NATIVE_TRIGGER_TRACE records no child-parent touch and the assembler must
 -- verify that composed trigger set. A shifted hook cannot silently qualify.
 if p_before->'sale'is distinct from p_actual->'sale'then
  raise exception 'CP7_CREDIT_SOURCE_HEADER_CHANGED_BEFORE_NATIVE_E';end if;
 foreach key in array array['items','allocations','return_items','payment_posting_facts','advance_links',
  'hpp_versions','opening_hpp_corrections','hpp_accounts','period_snapshot','nonpo_hpp_events','po_hpp_events']loop
  if p_actual->key is distinct from p_before->key then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_PRESERVED_FACT_CHANGED: %',key;end if;
 end loop;
 -- FIRST bounded vertical. These are pre-effect guards too, not a promise
 -- that a later adapter can adopt PO/recost/conversion synchronization.
 if p_before->'advance_links'<>'[]'::jsonb
  or exists(select 1 from jsonb_array_elements(p_before->'payments')x where
   x->>'cash_account_id'is null or x->>'payment_method'='OPENING_ADVANCE')then
  raise exception 'CP7_CREDIT_SOURCE_ADVANCE_INVERSE_UNQUALIFIED';end if;
 if exists(select 1 from jsonb_array_elements(p_before->'fg_lots')x where x->>'po_id'is not null)
  or p_before->'po_hpp_states'<>'[]'::jsonb then
  raise exception 'CP7_CREDIT_SOURCE_PO_HPP_INVERSE_UNQUALIFIED';end if;
 if p_before->'opening_hpp_corrections'<>'[]'::jsonb
  or exists(select 1 from jsonb_array_elements(p_before->'hpp_versions')x
   group by x->>'lot_id'having count(*)<>1)then
  raise exception 'CP7_CREDIT_SOURCE_RECOST_INVERSE_UNQUALIFIED';end if;
 if exists(select 1 from jsonb_array_elements(p_before->'fg_lots')x where x->>'lot_origin'='CONVERSION')then
  raise exception 'CP7_CREDIT_SOURCE_CONVERSION_INVERSE_UNQUALIFIED';end if;

 source_type:=case when p_action='RETURN_REVERSE'then'SALES_RETURN'else'SALES_PAYMENT'end;
 source_key:=case when p_action='RETURN_REVERSE'then'returns'else'payments'end;
 select count(*)into n from jsonb_array_elements(p_before->source_key)x where x->>'id'=p_source::text;
 if n<>1 then raise exception 'CP7_CREDIT_SOURCE_INVERSE_ORIGINAL_SOURCE_NOT_UNIQUE';end if;
 select x into strict old_source from jsonb_array_elements(p_before->source_key)x where x->>'id'=p_source::text;
 select x into strict new_source from jsonb_array_elements(p_actual->source_key)x where x->>'id'=p_source::text;
 if old_source->>'status'is distinct from'POSTED'or new_source->>'status'is distinct from'REVERSED'
  or old_source->>'sale_id'is distinct from sale_id::text
  or old_source-'status'is distinct from new_source-'status'then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_SOURCE_STATUS_OR_IDENTITY_CHANGED';end if;
 select cp7_credit.source_rows_v1(coalesce(jsonb_agg(case when x->>'id'=p_source::text
  then jsonb_set(x,'{status}','"REVERSED"')else x end),'[]'))into expected
  from jsonb_array_elements(p_before->source_key)x;
 if cp7_credit.source_rows_v1(p_actual->source_key)is distinct from expected then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_UNRELATED_SOURCE_CHANGED';end if;
 key:=case when p_action='RETURN_REVERSE'then'payments'else'returns'end;
 if p_before->key is distinct from p_actual->key then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_OTHER_SOURCE_KIND_CHANGED';end if;

 select count(*)into n from jsonb_array_elements(p_before->'journals')x where
  x#>>'{immutable_payload,journal,source_type}'=source_type
  and x#>>'{immutable_payload,journal,source_id}'=p_source::text;
 if n<>1 then raise exception 'CP7_CREDIT_SOURCE_INVERSE_ORIGINAL_JOURNAL_NOT_UNIQUE';end if;
 select x into strict original from jsonb_array_elements(p_before->'journals')x where
  x#>>'{immutable_payload,journal,source_type}'=source_type
  and x#>>'{immutable_payload,journal,source_id}'=p_source::text;
 original_id:=(original->>'id')::uuid;
 original_header:=jsonb_populate_record(null::erp.journal_entries,original#>'{immutable_payload,journal}');
 if original->>'status'is distinct from'POSTED'or original_header.id is distinct from original_id
  or original_header.reversal_of_id is not null then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_BAD_ORIGINAL_JOURNAL';end if;
 if exists(select 1 from jsonb_array_elements(p_before->'journals')x where
  x#>>'{immutable_payload,journal,source_id}'=original_id::text
  or x#>>'{immutable_payload,journal,reversal_of_id}'=original_id::text)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_ALREADY_EXISTED';end if;
 select count(*)into n from jsonb_array_elements(p_actual->'journals')x where
  x#>>'{immutable_payload,journal,source_type}'='JOURNAL_REVERSAL'
  and x#>>'{immutable_payload,journal,source_id}'=original_id::text
  and x#>>'{immutable_payload,journal,reversal_of_id}'=original_id::text;
 if n<>1 then raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_JOURNAL_NOT_UNIQUE';end if;
 select x into strict inverse from jsonb_array_elements(p_actual->'journals')x where
  x#>>'{immutable_payload,journal,source_type}'='JOURNAL_REVERSAL'
  and x#>>'{immutable_payload,journal,source_id}'=original_id::text
  and x#>>'{immutable_payload,journal,reversal_of_id}'=original_id::text;
 inverse_id:=(inverse->>'id')::uuid;
 inverse_header:=jsonb_populate_record(null::erp.journal_entries,inverse#>'{immutable_payload,journal}');
 if inverse->>'status'is distinct from'POSTED'or inverse_id is null or inverse_header.id is distinct from inverse_id
  or inverse_id=original_id then raise exception 'CP7_CREDIT_SOURCE_INVERSE_BAD_ACTUAL_JOURNAL';end if;
 select cp7_credit.source_rows_v1(coalesce(jsonb_agg(case when x->>'id'=original_id::text
  then jsonb_set(x,'{status}','"REVERSED"')else x end),'[]')||jsonb_build_array(inverse))into expected
  from jsonb_array_elements(p_before->'journals')x;
 if cp7_credit.source_rows_v1(p_actual->'journals')is distinct from expected then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_ORIGINAL_PAYLOAD_OR_JOURNAL_SET_CHANGED';end if;
 for row in select x from jsonb_array_elements(p_actual->'journals')x loop
  if cp7_credit.materialized_journal_payload((row->>'id')::uuid)is distinct from row->'immutable_payload'then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_IMMUTABLE_JOURNAL_CHANGED';end if;
 end loop;
 if cp7_credit.source_inverse_vector_v1(inverse#>'{immutable_payload,lines}')is distinct from
    cp7_credit.source_inverse_vector_v1(original#>'{immutable_payload,lines}',true)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_SIGNED_VECTOR_OR_DIMENSIONS_CHANGED';end if;
 if not exists(select 1 from jsonb_array_elements(inverse#>'{immutable_payload,lines}')x having
  sum((x->>'debit')::numeric)=sum((x->>'credit')::numeric)and sum((x->>'debit')::numeric)>0)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_UNBALANCED';end if;
 closed:=(p_before#>>'{period_snapshot,closed_through}')::date;
 lawful:=case when closed is not null and inverse_header.economic_date<=closed
  then greatest(inverse_header.economic_date,closed+1)else inverse_header.economic_date end;
 if inverse_header.economic_date is null or inverse_header.transaction_date is null or inverse_header.posting_at is null
  or inverse_header.economic_date is distinct from(inverse_header.posting_at at time zone'Asia/Jakarta')::date
  or inverse_header.transaction_date is distinct from lawful
  or inverse_header.economic_date<original_header.economic_date or inverse_header.posting_at<original_header.posting_at then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_DATE_PAIR_INVALID';end if;
 -- Historical period proof uses the captured resolver input, never today's
 -- control row. The Native inverse's economic day equals its actual posting day.
 select x into strict old_event from jsonb_array_elements(p_before->'base_events')x
  where x->>'id'='journal:'||original_id::text;
 select x into strict actual_event from jsonb_array_elements(p_actual->'base_events')x
  where x->>'id'='journal:'||inverse_id::text;
 select count(distinct c.ar_account_id),min(c.ar_account_id::text)::uuid into n,ar_account
  from cp7_credit.cohorts c where c.source_sale_id=sale_id;
 if n<>1 then raise exception 'CP7_CREDIT_SOURCE_HISTORICAL_AR_IDENTITY_UNQUALIFIED';end if;
 if old_event->>'kind'is distinct from case when p_action='RETURN_REVERSE'then'NET'else'FUNDING'end
  or actual_event->>'kind'is distinct from old_event->>'kind'
  or(actual_event->>'amount')::numeric is distinct from -(old_event->>'amount')::numeric
  or(actual_event->>'economic_date')::date is distinct from inverse_header.economic_date
  or(actual_event->>'transaction_date')::date is distinct from inverse_header.transaction_date
  or old_event->>'source_sha256'is distinct from ow04_source_proposal.sha(
   ow04_source_proposal.financial_journal_payload(original_id,ar_account))
  or actual_event->>'source_sha256'is distinct from ow04_source_proposal.sha(
   ow04_source_proposal.financial_journal_payload(inverse_id,ar_account))
  or(actual_event->>'amount')::numeric is distinct from(case when p_action='PAYMENT_REVERSE'then -1 else 1 end)*(
   select coalesce(sum((x->>'debit')::numeric-(x->>'credit')::numeric),0)
   from jsonb_array_elements(inverse#>'{immutable_payload,lines}')x where(x->>'account_id')::uuid=ar_account)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_EVENT_CHANGED';end if;
 if cp7_credit.source_rows_v1(p_actual->'base_events')is distinct from
  cp7_credit.source_rows_v1((p_before->'base_events')||jsonb_build_array(actual_event))then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_BASE_EVENT_DELTA_CHANGED';end if;

 if p_action='PAYMENT_REVERSE'then
  old_payment:=jsonb_populate_record(null::erp.sales_payments,old_source);
  new_payment:=jsonb_populate_record(null::erp.sales_payments,new_source);
  select x into strict fact_json from jsonb_array_elements(p_before->'payment_posting_facts')x
   where x->>'payment_id'=p_source::text;
  fact:=jsonb_populate_record(null::erp.sales_payment_posting_facts,fact_json);
  if fact.original_journal_entry_id is distinct from original_id or fact.sale_id is distinct from sale_id
   or fact.customer_id is distinct from(p_before#>>'{sale,customer_id}')::uuid
   or fact.payment_number is distinct from old_payment.payment_number
   or fact.payment_date is distinct from old_payment.payment_date or fact.amount is distinct from old_payment.amount
   or fact.cash_account_id is distinct from old_payment.cash_account_id
   or fact.replaces_payment_id is distinct from old_payment.replaces_payment_id
   or fact.payment_snapshot is distinct from old_source-'status'
   or fact.journal_economic_date is distinct from original_header.economic_date
   or fact.journal_transaction_date is distinct from original_header.transaction_date
   or fact.journal_posting_at is distinct from original_header.posting_at
   or fact.lineage_sha256 is distinct from cp7_credit.pg_jsonb_sha256(jsonb_build_array(
    fact.payment_id,fact.sale_id,fact.customer_id,fact.payment_number,fact.payment_date,fact.amount,
    fact.cash_account_id,fact.original_journal_entry_id,fact.journal_economic_date,fact.journal_transaction_date,
    fact.journal_posting_at,fact.replaces_payment_id,fact.predecessor_reversal_journal_id,fact.payment_snapshot))then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_PAYMENT_POSTING_FACT_INVALID';end if;
  if(select to_jsonb(f)from erp.sales_payment_posting_facts f where f.payment_id=p_source)is distinct from fact_json then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_POSTING_FACT_CHANGED';end if;
  if exists(select 1 from jsonb_array_elements(p_before->'payment_reversal_facts')x where x->>'payment_id'=p_source::text)then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_PAYMENT_FACT_ALREADY_EXISTED';end if;
  select x into strict reversal_json from jsonb_array_elements(p_actual->'payment_reversal_facts')x
   where x->>'payment_id'=p_source::text;
  reversal_fact:=jsonb_populate_record(null::erp.sales_payment_reversal_facts,reversal_json);
  if(reversal_fact.original_journal_entry_id,reversal_fact.reversal_journal_entry_id,
    reversal_fact.reversal_economic_date,reversal_fact.reversal_transaction_date,reversal_fact.reversal_posting_at)is distinct from
   (original_id,inverse_id,inverse_header.economic_date,inverse_header.transaction_date,inverse_header.posting_at)
   or reversal_fact.lineage_sha256 is distinct from cp7_credit.pg_jsonb_sha256(jsonb_build_array(
    reversal_fact.payment_id,reversal_fact.original_journal_entry_id,reversal_fact.reversal_journal_entry_id,
    reversal_fact.reversal_economic_date,reversal_fact.reversal_transaction_date,reversal_fact.reversal_posting_at))then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_PAYMENT_REVERSAL_FACT_INVALID';end if;
  if cp7_credit.source_rows_v1(p_actual->'payment_reversal_facts')is distinct from
    cp7_credit.source_rows_v1((p_before->'payment_reversal_facts')||jsonb_build_array(reversal_json))
   or(select to_jsonb(f)from erp.sales_payment_reversal_facts f where f.payment_id=p_source)is distinct from reversal_json then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_REVERSAL_FACT_SET_CHANGED';end if;
  -- hpp_support includes ALLOCATION.sale = to_jsonb(sales_headers), including
  -- status/version/touch time. It is not a physical immutability predicate.
  -- Preserve every raw physical/HPP fact and full HPP J instead.
  foreach key in array array['fg_lots','stock_movements','inventory_balances','opening_hpp_states',
   'po_hpp_states','hpp_journals']loop
   if p_before->key is distinct from p_actual->key then
    raise exception 'CP7_CREDIT_SOURCE_INVERSE_PAYMENT_CHANGED_PHYSICAL_OR_HPP_FACTS: %',key;end if;
  end loop;
 else
  if p_actual->'payment_reversal_facts'is distinct from p_before->'payment_reversal_facts'then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_RETURN_CHANGED_PAYMENT_FACTS';end if;
  -- Physical bijection and cache arithmetic are delegated to another complete
  -- predicate, supplied in 02. That helper has no authority or work dependency.
  proof:=cp7_credit.source_return_stock_proof_v1(p_before,p_actual,p_source);
 end if;
 -- All relevant HPP journals are an exact before-set plus, for return only,
 -- the actual source inverse. This excludes hidden Native sync/revaluation J.
 expected:=p_before->'hpp_journals';
 if p_action='RETURN_REVERSE'then
  select cp7_credit.source_rows_v1(coalesce(jsonb_agg(case when x->>'id'=original_id::text
   then jsonb_set(x,'{status}','"REVERSED"')else x end),'[]')||case when exists(
    select 1 from jsonb_array_elements(p_before->'hpp_journals')z where z->>'id'=original_id::text)
    then jsonb_build_array(inverse)else'[]'::jsonb end)into expected
   from jsonb_array_elements(p_before->'hpp_journals')x;
 end if;
 if cp7_credit.source_rows_v1(p_actual->'hpp_journals')is distinct from cp7_credit.source_rows_v1(expected)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_UNQUALIFIED_HPP_JOURNAL_EFFECT';end if;
 for row in select x from jsonb_array_elements(p_actual->'hpp_journals')x loop
  if cp7_credit.materialized_journal_payload((row->>'id')::uuid)is distinct from row->'immutable_payload'then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_HPP_JOURNAL_CHANGED';end if;
 end loop;
 return jsonb_build_object('contract_version','ow04.native-source-inverse-proof.v1','action',p_action,
  'source_id',p_source,'sale_id',sale_id,'original_journal_id',original_id,'inverse_journal_id',inverse_id,
  'original_immutable_journal_sha256',cp7_credit.pg_jsonb_sha256(original->'immutable_payload'),
  'inverse_immutable_journal_sha256',cp7_credit.pg_jsonb_sha256(inverse->'immutable_payload'),
  'inverse_signed_vector_sha256',cp7_credit.pg_jsonb_sha256(cp7_credit.source_inverse_vector_v1(inverse#>'{immutable_payload,lines}')),
  'actual_event',actual_event,'actual_event_sha256',cp7_credit.pg_jsonb_sha256(actual_event),
  'actual_pair',jsonb_build_object('economic_date',inverse_header.economic_date,'transaction_date',inverse_header.transaction_date),
  'period_snapshot_sha256',cp7_credit.pg_jsonb_sha256(p_before->'period_snapshot'),
  'before_source_sha256',cp7_credit.pg_jsonb_sha256(p_before),'actual_source_sha256',cp7_credit.pg_jsonb_sha256(p_actual),
  'payment_posting_fact_sha256',case when fact_json is not null then cp7_credit.pg_jsonb_sha256(fact_json)end,
  'payment_reversal_fact_sha256',case when reversal_json is not null then cp7_credit.pg_jsonb_sha256(reversal_json)end,
  'physical_proof',proof,'additional_native_hpp_sync_effects',0);
end $$;

create function cp7_credit.assert_source_materialization_v1(p_operation uuid)returns void
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare m cp7_credit.source_operation_materializations_v1;f cp7_credit.financial_materializations;
 sp cp7_credit.source_operation_plans_v1;p cp7_credit.recognition_plans;s cp7_credit.source_operation_part_seals_v1;
 binding text;family jsonb;input_family jsonb;k jsonb;objects jsonb;new_objects jsonb;old_object jsonb;retained_before jsonb;retained_after jsonb;
 side text;support_events jsonb;ar uuid;before_i numeric;
begin
 select *into strict m from cp7_credit.source_operation_materializations_v1 where operation_id=p_operation;
 binding:=cp7_credit.source_operation_binding_sha256_v1(m.operation_id);
 if m.payload_sha256 is distinct from cp7_credit.pg_jsonb_sha256(m.payload)
  or m.actual_manifest_sha256 is distinct from cp7_credit.pg_jsonb_sha256(cp7_credit.source_materialization_manifest_v1(m.operation_id))
  or m.plan_manifest is distinct from cp7_credit.source_stored_plan_manifest_v1(m.operation_id)
  or m.before_ordinal_input is distinct from cp7_credit.source_historical_ordinal_input_v1(m.operation_id,false)
  or m.actual_ordinal_input is distinct from cp7_credit.source_historical_ordinal_input_v1(m.operation_id,true)
  or m.before_financial_profile->'actual_objects'is distinct from cp7_credit.source_historical_objects_v1(m.operation_id)
  or m.before_ordinal_result is distinct from ow04_ordinal_wrapper.reconcile_v1(m.before_ordinal_input)
  or m.actual_ordinal_result is distinct from ow04_ordinal_wrapper.reconcile_v1(m.actual_ordinal_input)
  or not coalesce((m.before_ordinal_result->>'arithmetic_supported')::boolean,false)
  or not coalesce((m.actual_ordinal_result->>'arithmetic_supported')::boolean,false)
  or exists(select 1 from jsonb_array_elements(m.before_ordinal_result->'families')x where(x->>'has_reconciliation_effect')::boolean)
  or m.actual_source_proof is distinct from cp7_credit.source_inverse_proof_v1(m.before_source,m.actual_source,m.action,m.source_id)then
  raise exception 'CP7_CREDIT_SOURCE_MATERIALIZATION_BINDING_CHANGED';end if;
 -- Family registration, retained I and consumers are unchanged by a source
 -- operation. Only actual Native source events may change its target.
 select coalesce(jsonb_agg(x-'events'order by(x->>'ordinal')::bigint),'[]')into retained_before
  from jsonb_array_elements(m.before_ordinal_input->'families')x;
 select coalesce(jsonb_agg(x-'events'order by(x->>'ordinal')::bigint),'[]')into retained_after
  from jsonb_array_elements(m.actual_ordinal_input->'families')x;
 if retained_before is distinct from retained_after or m.actual_ordinal_input->>'family_root_sale_id'<>m.sale_id::text
  or m.before_ordinal_input->>'family_root_sale_id'<>m.sale_id::text then
  raise exception 'CP7_CREDIT_SOURCE_RETAINED_BASELINE_CHANGED';end if;
 select coalesce(sum((e->>'amount')::numeric),0)into before_i
  from jsonb_array_elements(m.before_ordinal_input->'families')f,lateral jsonb_array_elements(f->'retained_recognition')e;
 if m.before_financial_profile->>'actual_objects_sha256'is distinct from cp7_credit.pg_jsonb_sha256(m.before_financial_profile->'actual_objects')
  or(m.before_financial_profile->>'I')::numeric is distinct from before_i
  or(m.before_financial_profile->>'U')::numeric is distinct from 0::numeric
  or(m.before_financial_profile->>'adjustment')::numeric is distinct from -before_i
  or(m.before_financial_profile->>'sale_id',m.before_financial_profile->>'root_sale_id',m.before_financial_profile->>'current_leaf_id')
   is distinct from(m.sale_id::text,m.sale_id::text,m.sale_id::text)then
  raise exception 'CP7_CREDIT_SOURCE_BEFORE_FINANCIAL_PROFILE_CHANGED';end if;
 for sp in select *from cp7_credit.source_operation_plans_v1 where operation_id=m.operation_id order by family_ordinal loop
  select *into strict p from cp7_credit.recognition_plans where id=sp.plan_id;
  select x into strict family from jsonb_array_elements(m.actual_ordinal_result->'families')x
   where x#>>'{registration,family_id}'=sp.family_id::text;
  select x into strict input_family from jsonb_array_elements(m.actual_ordinal_input->'families')x
   where x->>'family_id'=sp.family_id::text;
  k:=cp7_credit.source_adjustment_kernel_v1(family);
  if not coalesce((family->>'has_reconciliation_effect')::boolean,false)or jsonb_array_length(k->'components')=0
   or p.net_amount>=0 or sp.full_family_result is distinct from family or sp.canonical_plan is distinct from k
   or sp.before_retained_events is distinct from input_family->'retained_recognition'
   or sp.before_consumptions is distinct from input_family->'consumptions'
   or family->>'retained_recognition_sha256'is distinct from ow04_pure_kernel.vector_sha256_v1(sp.before_retained_events)
   or family->>'consumptions_sha256'is distinct from ow04_pure_kernel.vector_sha256_v1(sp.before_consumptions)
   or sp.source_binding_sha256 is distinct from binding
   or(p.plan_kind,p.owning_action,p.actor,p.request_id,p.payload_sha256,p.review_sha256,p.family_root_sale_id)is distinct from
    ('ADJUSTMENT',m.action,m.actor,m.request_id,m.payload_sha256,binding,m.sale_id)
   or p.kernel_result is distinct from k or p.net_amount is distinct from(k->>'net_current_k')::numeric
   or p.kernel_version is distinct from k->>'kernel_version'
   or p.before_events is distinct from k->'before_events'or p.added_events is distinct from k->'added_events'
   or p.before_source_sha256 is distinct from k->>'before_source_sha256'
   or p.after_source_sha256 is distinct from k->>'after_source_sha256'
   or p.support_sha256_pg is distinct from cp7_credit.pg_jsonb_sha256(k->'support')
   or p.components_sha256_pg is distinct from cp7_credit.pg_jsonb_sha256(k->'components')
   or p.expected_component_count is distinct from jsonb_array_length(k->'components')
   or p.has_recognition_effect is distinct from(jsonb_array_length(k->'components')>0)
   or exists(select 1 from cp7_credit.plan_dependencies d where d.plan_id=p.id)
   or exists(select 1 from jsonb_array_elements(k->'components')x where(x->>'amount')::numeric>=0)
   or exists(select 1 from cp7_credit.cohorts ch where ch.id=p.cohort_id and ch.family_id<>sp.family_id)
   or not exists(select 1 from cp7_credit.return_families rf where rf.id=sp.family_id and rf.family_root_sale_id=m.sale_id and rf.family_ordinal=sp.family_ordinal)then
   raise exception 'CP7_CREDIT_SOURCE_SIGNED_PLAN_PROVENANCE_CHANGED';end if;
  select ar_account_id into strict ar from cp7_credit.cohorts where id=p.cohort_id;
  foreach side in array array['BEFORE','ADDED']loop
   select coalesce(jsonb_agg(jsonb_build_object('id',s0.event_id,'kind',s0.kind,'amount',cp7_credit.cent_text(s0.amount),
    'economic_date',s0.economic_date::text,'transaction_date',s0.transaction_date::text,'source_sha256',s0.source_sha256)
    order by s0.event_id collate"C"),'[]')into support_events from cp7_credit.plan_support_events s0 where s0.plan_id=p.id and s0.phase=side;
   if support_events is distinct from(case when side='BEFORE'then k->'before_events'else k->'added_events'end)then
    raise exception 'CP7_CREDIT_SOURCE_RETAINED_SUPPORT_VECTOR_CHANGED';end if;
  end loop;
  if exists(select 1 from cp7_credit.plan_support_events s0 where s0.plan_id=p.id and
   (s0.event_id is distinct from'journal:'||s0.journal_id::text
    or s0.source_fact_snapshot is distinct from ow04_source_proposal.financial_journal_payload(s0.journal_id,ar)
    or s0.source_sha256 is distinct from ow04_source_proposal.sha(s0.source_fact_snapshot)))then
   raise exception 'CP7_CREDIT_SOURCE_RETAINED_SUPPORT_FACT_CHANGED';end if;
 end loop;
 if exists(select 1 from cp7_credit.recognition_plans p0 where p0.actor=m.actor and p0.request_id=m.request_id
  and not exists(select 1 from cp7_credit.source_operation_plans_v1 sp0 where sp0.operation_id=m.operation_id and sp0.plan_id=p0.id))
  or exists(select 1 from jsonb_array_elements(m.actual_ordinal_result->'families')x where(x->>'has_reconciliation_effect')::boolean
   and not exists(select 1 from cp7_credit.source_operation_plans_v1 sp0 where sp0.operation_id=m.operation_id and sp0.family_id=(x#>>'{registration,family_id}')::uuid))then
  raise exception 'CP7_CREDIT_SOURCE_SIGNED_PLAN_SET_INCOMPLETE';end if;
 for s in select *from cp7_credit.source_operation_part_seals_v1 where operation_id=m.operation_id loop
  if s.actual_journal_sha256 is distinct from cp7_credit.pg_jsonb_sha256(s.actual_journal)
   or s.actual_journal is distinct from cp7_credit.materialized_journal_payload(s.journal_id)
   or s.source_binding_sha256 is distinct from binding
   or s.journal_link is distinct from(select to_jsonb(j)from cp7_credit.component_journals j where j.part_id=s.part_id and j.journal_id=s.journal_id)
   or not exists(select 1 from cp7_credit.component_parts q join cp7_credit.recognition_components cc on cc.id=q.component_id
    join cp7_credit.source_operation_plans_v1 sp0 on sp0.plan_id=cc.plan_id where q.id=s.part_id and cc.id=s.component_id
     and cc.plan_id=s.plan_id and sp0.operation_id=m.operation_id)
   or not exists(select 1 from erp.journal_entries j where j.id=s.journal_id and j.status='POSTED')
   or exists(select 1 from erp.journal_entries j where j.reversal_of_id=s.journal_id or(j.source_type='JOURNAL_REVERSAL'and j.source_id=s.journal_id))then
   raise exception 'CP7_CREDIT_SOURCE_PART_SEAL_CHANGED';end if;
 end loop;
 if exists(select 1 from cp7_credit.source_operation_plans_v1 sp0 join cp7_credit.recognition_components cc on cc.plan_id=sp0.plan_id
  join cp7_credit.component_parts q on q.component_id=cc.id where sp0.operation_id=m.operation_id
   and not exists(select 1 from cp7_credit.source_operation_part_seals_v1 s0 where s0.operation_id=m.operation_id and s0.part_id=q.id))then
  raise exception 'CP7_CREDIT_SOURCE_PART_SEAL_INCOMPLETE';end if;
 objects:=cp7_credit.current_materialized_objects(m.sale_id,m.sale_id,m.sale_id)->'actual_objects';
 for old_object in select value from jsonb_array_elements(m.before_financial_profile->'actual_objects')loop
  if not exists(select 1 from jsonb_array_elements(objects)x where x=old_object)then
   raise exception 'CP7_CREDIT_SOURCE_OLD_FINANCIAL_HISTORY_CHANGED';end if;
 end loop;
 select coalesce(jsonb_agg(x order by x->>'object_kind'collate"C",x->>'object_id'collate"C"),'[]')into new_objects
  from jsonb_array_elements(objects)x where
   (x->>'object_kind'='PLAN'and exists(select 1 from cp7_credit.source_operation_plans_v1 sp0 where sp0.operation_id=m.operation_id and sp0.plan_id=(x->>'object_id')::uuid))
   or(x->>'object_kind'='COMPONENT'and exists(select 1 from cp7_credit.recognition_components cc join cp7_credit.source_operation_plans_v1 sp0 on sp0.plan_id=cc.plan_id
    where sp0.operation_id=m.operation_id and cc.id=(x->>'object_id')::uuid))
   or(x->>'object_kind'in('PART','PART_JOURNAL')and exists(select 1 from cp7_credit.component_parts q join cp7_credit.recognition_components cc on cc.id=q.component_id
    join cp7_credit.source_operation_plans_v1 sp0 on sp0.plan_id=cc.plan_id where sp0.operation_id=m.operation_id and q.id=(x->>'object_id')::uuid));
 if new_objects is distinct from m.actual_objects or(jsonb_array_length(new_objects)=0)is distinct from(m.financial_marker_id is null)then
  raise exception 'CP7_CREDIT_SOURCE_ACTUAL_OBJECT_SET_CHANGED';end if;
 if m.financial_marker_id is not null then
  select *into strict f from cp7_credit.financial_materializations where id=m.financial_marker_id;
  if(f.root_sale_id,f.actor,f.request_id,f.request_ordinal,f.owning_action,f.payload_sha256,f.source_plan_sha256)is distinct from
   (m.sale_id,m.actor,m.request_id,1,m.action,m.payload_sha256,binding)
   or f.actual_objects is distinct from m.actual_objects or f.actual_objects_sha256 is distinct from cp7_credit.pg_jsonb_sha256(m.actual_objects)
   or exists(select 1 from jsonb_array_elements(m.actual_objects)x where not exists(select 1 from cp7_credit.financial_materialization_objects o
    where o.materialization_id=f.id and o.object_kind=x->>'object_kind'and o.object_id=(x->>'object_id')::uuid and o.fact_sha256=x->>'fact_sha256'))
   or(select count(*)from cp7_credit.financial_materialization_objects where materialization_id=f.id)<>jsonb_array_length(m.actual_objects)then
   raise exception 'CP7_CREDIT_SOURCE_FINANCIAL_MARKER_CHANGED';end if;
 end if;
end $$;

create function cp7_credit.assert_source_adjustment_part_journal_v1(p_part uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare q cp7_credit.component_parts;c cp7_credit.recognition_components;o cp7_credit.component_journals;j erp.journal_entries;
 actual_lines jsonb;
begin
 select *into strict q from cp7_credit.component_parts where id=p_part;
 select *into strict c from cp7_credit.recognition_components where id=q.component_id;
 select *into strict o from cp7_credit.component_journals where part_id=q.id;
 select *into strict j from erp.journal_entries where id=o.journal_id;
 select coalesce(jsonb_agg(jsonb_build_object('account_id',l.account_id,'customer_id',l.customer_id,'vendor_id',l.vendor_id,
  'contractor_id',l.contractor_id,'product_id',l.product_id,'po_id',l.po_id,'debit',l.debit,'credit',l.credit)),'[]')into actual_lines
  from erp.journal_lines l where l.journal_entry_id=j.id;
 if(j.source_type,j.source_id,j.reversal_of_id,j.economic_date,j.transaction_date,j.status)is distinct from
   ('CP7_CUSTOMER_CREDIT_RECOGNITION',q.id,null::uuid,c.economic_date,c.transaction_date,'POSTED')
  or(o.economic_date,o.transaction_date,o.lines_sha256_pg)is distinct from
   (c.economic_date,c.transaction_date,cp7_credit.native_lines_sha256(cp7_credit.part_lines(q.id)))
  or jsonb_array_length(actual_lines)<>2
  or cp7_credit.initial_line_semantics_v1(actual_lines)is distinct from cp7_credit.initial_line_semantics_v1(cp7_credit.part_lines(q.id))
  or exists(select 1 from erp.journal_entries x where x.reversal_of_id=j.id or(x.source_type='JOURNAL_REVERSAL'and x.source_id=j.id))
  or(select count(*)from erp.journal_entries x where x.source_type='CP7_CUSTOMER_CREDIT_RECOGNITION'and x.source_id=q.id)<>1 then
  raise exception 'CP7_CREDIT_SOURCE_PART_ACTUAL_JOURNAL_CHANGED';end if;
end $$;

create function cp7_credit.assert_source_operation_part_seals_v1(p_operation uuid,p_just_linked uuid default null)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;x cp7_credit.posting_scope;r record;
 v_part cp7_credit.component_parts;v_component cp7_credit.recognition_components;v_cohort cp7_credit.cohorts;
begin
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=p_operation;
 if p_just_linked is not null then
  select *into strict x from cp7_credit.posting_scope where backend_pid=w.backend_pid and transaction_id=w.transaction_id and actor=w.actor;
  select *into strict v_part from cp7_credit.component_parts where id=p_just_linked;
  select *into strict v_component from cp7_credit.recognition_components where id=v_part.component_id;
  select ch.*into strict v_cohort from cp7_credit.cohorts ch join cp7_credit.recognition_plans p on p.cohort_id=ch.id where p.id=v_component.plan_id;
  if(x.request_id,x.post_kind,x.plan_id,x.component_id,x.part_id,x.source_sale_id,x.source_return_id,
    x.source_type,x.source_id,x.economic_date,x.transaction_date,x.lines_sha256_pg)is distinct from
   (w.request_id,'COMPONENT',v_component.plan_id,v_component.id,v_part.id,v_cohort.source_sale_id,v_cohort.source_return_id,
    'CP7_CUSTOMER_CREDIT_RECOGNITION',v_part.id,v_component.economic_date,v_component.transaction_date,cp7_credit.native_lines_sha256(cp7_credit.part_lines(v_part.id)))
   or v_component.plan_id is distinct from w.active_plan_id
   or not exists(select 1 from cp7_credit.source_operation_plans_v1 sp where sp.operation_id=w.operation_id and sp.plan_id=v_component.plan_id)
   or exists(select 1 from cp7_credit.source_operation_part_seals_v1 where part_id=p_just_linked)
   or not exists(select 1 from cp7_credit.component_journals where part_id=p_just_linked)then
   raise exception 'CP7_CREDIT_SOURCE_JUST_LINKED_SCOPE_REQUIRED';end if;
 end if;
 -- Exact link->seal and seal->link; missing or extra sealed identities refuse.
 if exists(select 1 from cp7_credit.source_operation_plans_v1 sp join cp7_credit.recognition_components c on c.plan_id=sp.plan_id
  join cp7_credit.component_parts q on q.component_id=c.id join cp7_credit.component_journals o on o.part_id=q.id
  where sp.operation_id=w.operation_id and q.id is distinct from p_just_linked and not exists(
   select 1 from cp7_credit.source_operation_part_seals_v1 z where z.operation_id=w.operation_id and z.plan_id=sp.plan_id
    and z.component_id=c.id and z.part_id=q.id and z.journal_id=o.journal_id))
  or exists(select 1 from cp7_credit.source_operation_part_seals_v1 z where z.operation_id=w.operation_id and not exists(
   select 1 from cp7_credit.source_operation_plans_v1 sp join cp7_credit.recognition_components c on c.plan_id=sp.plan_id
    join cp7_credit.component_parts q on q.component_id=c.id join cp7_credit.component_journals o on o.part_id=q.id
    where sp.operation_id=w.operation_id and(sp.plan_id,c.id,q.id,o.journal_id)=(z.plan_id,z.component_id,z.part_id,z.journal_id)))then
  raise exception 'CP7_CREDIT_SOURCE_PART_SEAL_SET_CHANGED';end if;
 for r in select q.id part_id,to_jsonb(o) journal_link,z.actual_journal,z.actual_journal_sha256,z.source_binding_sha256,o.journal_id
  from cp7_credit.source_operation_plans_v1 sp join cp7_credit.recognition_components c on c.plan_id=sp.plan_id
  join cp7_credit.component_parts q on q.component_id=c.id left join cp7_credit.component_journals o on o.part_id=q.id
  left join cp7_credit.source_operation_part_seals_v1 z on z.part_id=q.id where sp.operation_id=w.operation_id loop
  -- A Native J without its immutable link is never excluded/ignored as pending.
  if r.journal_id is null then
   if exists(select 1 from erp.journal_entries j where j.source_type='CP7_CUSTOMER_CREDIT_RECOGNITION'and j.source_id=r.part_id)then
    raise exception 'CP7_CREDIT_SOURCE_ORPHAN_PART_JOURNAL';end if;
   continue;
  end if;
  perform cp7_credit.assert_source_adjustment_part_journal_v1(r.part_id);
  if r.part_id is not distinct from p_just_linked then continue;end if;
  if r.journal_link is distinct from(select z.journal_link from cp7_credit.source_operation_part_seals_v1 z where z.part_id=r.part_id)
   or r.actual_journal is distinct from cp7_credit.materialized_journal_payload(r.journal_id)
   or r.actual_journal_sha256 is distinct from cp7_credit.pg_jsonb_sha256(r.actual_journal)
   or r.source_binding_sha256 is distinct from cp7_credit.source_operation_binding_sha256_v1(w.operation_id)then
   raise exception 'CP7_CREDIT_SOURCE_PART_SEAL_CHANGED';end if;
 end loop;
end $$;

create function cp7_credit.seal_source_operation_part_v1(p_part uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare q cp7_credit.component_parts;c cp7_credit.recognition_components;s cp7_credit.source_operation_plans_v1;
 o cp7_credit.component_journals;actual jsonb;
begin
 select *into strict q from cp7_credit.component_parts where id=p_part;
 select *into strict c from cp7_credit.recognition_components where id=q.component_id;
 select *into strict s from cp7_credit.source_operation_plans_v1 where plan_id=c.plan_id;
 perform cp7_credit.assert_source_adjustment_owner_base_v1(c.plan_id);
 perform cp7_credit.assert_source_retained_journals_v1(s.operation_id);
 -- Allows this one just-created link, only under its still-live exact posting
 -- scope. Every other part is checked against its existing immutable seal.
 perform cp7_credit.assert_source_operation_part_seals_v1(s.operation_id,q.id);
 select *into strict o from cp7_credit.component_journals where part_id=q.id;
